from fastapi import FastAPI, APIRouter
import pytest

def test_include_router_self():
    app = FastAPI()
    try:
        app.include_router(app)
    except Exception as e:
        print(f"Caught expected exception: {e}")
        return
    print("Did not catch any exception")

def test_include_router_self_router():
    router = APIRouter()
    try:
        router.include_router(router)
    except Exception as e:
        print(f"Caught expected exception: {e}")
        return
    print("Did not catch any exception")

if __name__ == "__main__":
    test_include_router_self()
    test_include_router_self_router()

